#include <vector>
#include <complex>
#include <algorithm>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort:
    // In each phase, disjoint adjacent pairs are compared/swapped in parallel.
    // This is correct for any thread count.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2; // even phase: (0,1),(2,3)...; odd phase: (1,2),(3,4)...

        #pragma omp parallel for default(none) shared(x, n, start)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start); 
             i + 1 < static_cast<std::ptrdiff_t>(n); 
             i += 2) {
            const std::complex<double> a = x[static_cast<std::size_t>(i)];
            const std::complex<double> b = x[static_cast<std::size_t>(i + 1)];

            const double ma = std::norm(a); // squared magnitude
            const double mb = std::norm(b);

            if (ma > mb) {
                x[static_cast<std::size_t>(i)]     = b;
                x[static_cast<std::size_t>(i + 1)] = a;
            }
        }
    }
}
